"""v61 — QB Targets (Intel) · Live Categories (Home) · Category Grid v2 gets v1's per-category record columns. Rerunnable."""
import os, sys
os.chdir(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'))
P = 'scripts/dashboard_template.html'
s = open(P, encoding='utf-8').read()
if '/* v61 */' in s:
    print('v61 already applied'); sys.exit(0)

def rep(old, new, n=1):
    global s
    assert s.count(old) == n, (s.count(old), old[:90])
    s = s.replace(old, new)

