# ---------- Category Grid v2: per-category record columns (v1's readability) ----------
rep("""    const V={player:x=>x.name,team:x=>x.team,pos:x=>x.pos,opp:x=>x.opp||'zz',cat:x=>x.cat,rec:x=>wgRec(x)??-1,hn:x=>x.hn,tp:x=>wgTp(x)??-1,res:x=>x.done?x.done.td:-1};
    const L=R.filter(x=>x.cat>0).sort((a,b)=>{const u=V[sortK](a),v=V[sortK](b);return (u<v?-1:u>v?1:0)*(sortA?1:-1)||b.cat-a.cat||(wgTp(b)??-1)-(wgTp(a)??-1)});""",
    """    const V={player:x=>x.name,team:x=>x.team,pos:x=>x.pos,opp:x=>x.opp||'zz',cat:x=>x.cat,rec:x=>wgRec(x)??-1,hn:x=>x.hn,tp:x=>wgTp(x)??-1,res:x=>x.done?x.done.td:-1};
    /* v61 */const V2=(x,k)=>k.startsWith('c:')?(c=>c?(c.now?1:0)+(c.n?c.k/c.n:0)/2+(c.n?.001:0):-1)(x.cells[k.slice(2)]):V[k](x);
    const L=R.filter(x=>x.cat>0).sort((a,b)=>{const u=V2(a,sortK),v=V2(b,sortK);return (u<v?-1:u>v?1:0)*(sortA?1:-1)||b.cat-a.cat||(wgTp(b)??-1)-(wgTp(a)??-1)});
    const ab=r=>esc(WG_AB[r.s.id]||r.s.ab||(r.s.lbl.length>11?r.s.lbl.slice(0,10)+'…':r.s.lbl));
    const ccell=(x,r)=>{const c=x.cells[r.s.id];if(!c||(!c.now&&!c.n))return '<td class="n g2c" data-v="-1"><span class="dim">·</span></td>';const hr=c.n?c.k/c.n:null;
      const sty=c.now?(hr!=null?gradeStyle(NT-Math.round(hr*(NT-1)),NT):'background:var(--edge2);color:var(--fg)'):'';
      return `<td class="n g2c${c.now?' on':''}" data-v="${(c.now?1:0)+(hr||0)/2}" title="${esc(`${r.s.lbl}: ${c.now?'carries it into week '+W0:'does not carry it in'} · carried it in ${c.n} of his ${x.gp} recorded games, scored in ${c.k}`)}">${c.now?`<span class="badge" style="${sty}">✓ ${c.n?c.k+'/'+c.n:'new'}</span>`:`<span class="dim mini">${c.k}/${c.n}</span>`}</td>`};""")
rep("""${th('cat','categories','how many reliable categories he carries in')}${th('rec','REC','scored in k of n earlier games where he carried one')}""",
    """${th('cat','#','how many reliable categories he carries in')}${PKs.map(r=>th('c:'+r.s.id,ab(r),r.s.lbl+' · ✓ = carries it in · k/n = scored in k of the n earlier games he carried it')).join('')}${th('rec','REC','scored in k of n earlier games where he carried one')}""")
rep("""<td class="n" data-v="${x.cat}">${sq(x)} <b>${x.cat}</b></td>""", """<td class="n" data-v="${x.cat}"><b>${x.cat}</b></td>${PKs.map(r=>ccell(x,r)).join('')}""")
rep("""squares = the categories he carries (hover for names) · REC = how often he scored when he carried them in earlier weeks · every column sorts""",
    """one column per reliable category: ✓ k/n = he carries it in and scored in k of the n earlier games he carried it (shaded by that rate) · grey k/n = his record without carrying it in · REC = all of them together · every column sorts""")

