if "data['qbTargets']" not in b:
    old = "    data['injuries'] = rows_of('data/processed/injuries_current.csv')\n"
    assert b.count(old) == 1
    b = b.replace(old, old + "    data['qbTargets'] = json.load(open('data/processed/qb_targets.json', encoding='utf-8')) if os.path.exists('data/processed/qb_targets.json') else None  # v61\n    data['categories'] = json.load(open('data/processed/categories.json', encoding='utf-8')) if os.path.exists('data/processed/categories.json') else None  # v61\n")
    open(B, 'w', encoding='utf-8').write(b)
print('v61 applied')
